const $=id=>document.getElementById(id);
const names={explore:['El Metro, desde otra perspectiva.','Acércate a cada detalle, resuelve una avería o toma los mandos. Tú eliges por dónde empezar.'],maintenance:['Repara con tus manos.','Elige una actividad. Arrastra las piezas, gira las herramientas y comprueba la reparación.']};
function highlight(mode){document.body.dataset.experience=mode;for(const b of document.querySelectorAll('.experience-nav [data-experience]')){if(b.dataset.experience===mode)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}if(names[mode]){document.querySelector('.workshop-heading h1').textContent=names[mode][0];document.querySelector('.workshop-heading p').textContent=names[mode][1];}}
for(const b of document.querySelectorAll('.experience-nav [data-experience]'))b.onclick=()=>{const mode=b.dataset.experience;if(document.body.dataset.workspace==='simulation')$('return-workshop').click();const target={explore:'mode-explore',maintenance:'mode-maintenance',automatic:'mode-simulator',operator:'mode-operate'}[mode];$(target).click();highlight(mode);window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};
window.addEventListener('workshop-mode',e=>highlight(e.detail));
const observer=new MutationObserver(()=>{if(document.body.dataset.workspace==='simulation')highlight(document.body.dataset.driving==='true'?'operator':'automatic');else highlight(document.body.dataset.workshopMode||'explore');});observer.observe(document.body,{attributes:true,attributeFilter:['data-workspace','data-driving','data-workshop-mode']});
$('interface-help').onclick=()=>$('interface-help-dialog').showModal();$('interface-help-close').onclick=()=>$('interface-help-dialog').close();
highlight('explore');
